mapper.insert:
INSERT INTO batch_operation_work (job_name, run_id, id, name, email, status, updated_at, version, detail)
SELECT #{scope.run.job}, #{scope.run.runId}, c.id, c.name, c.email, c.status, c.updated_at, c.version,
       #{scope.targetStatus}
FROM customer c
WHERE  AND c.status IS DISTINCT FROM #{scope.targetStatus}
ORDER BY c.id LIMIT #{limit}

