mapper.insert:
INSERT INTO batch_input_applied (consumer, bucket, object_key, revision, run_id)
SELECT #{job}, bucket, object_key, coalesce(version_id, etag), #{runId}
FROM batch_input WHERE job_name = #{job} AND run_id = #{runId}
ON CONFLICT DO NOTHING

INSERT INTO batch_operation_work (job_name, run_id, id, name, email, status, updated_at, version)
SELECT #{scope.run.job}, #{scope.run.runId}, c.id, c.name, c.email, c.status, c.updated_at, c.version
FROM batch_input_work i
JOIN customer c ON c.id = i.customer_id AND c.version = i.expected_version
WHERE i.job_name = #{scope.run.job} AND i.run_id = #{scope.run.runId}
ORDER BY c.id LIMIT #{limit}

INSERT INTO batch_patch_row (plan_id, id, old_status, new_status, old_version)
SELECT #{request.planId}, c.id, c.status, #{request.scope.targetStatus}, c.version
FROM customer c
WHERE c.id BETWEEN #{request.scope.idFrom} AND #{request.scope.idTo}
  AND c.updated_at >= #{request.scope.from} AND c.updated_at < #{request.scope.to}
  AND c.status IS DISTINCT FROM #{request.scope.targetStatus}
  AND c.status = #{request.scope.status}
ORDER BY c.id LIMIT #{limit}

mapper.select:
SELECT id FROM batch_patch_row
WHERE plan_id = #{planId} AND id > #{after}
ORDER BY id LIMIT #{limit}

SELECT id, old_status, new_status, old_version, applied_version, restored_version
FROM batch_patch_row WHERE plan_id = #{planId}
ORDER BY id
